import fs from 'node:fs';
import {createHash} from 'node:crypto';
const source='tmp/helmet-clip-candidate-20261007/head-probe.json';
const probe=JSON.parse(fs.readFileSync(source,'utf8'));
if(probe.dimensions!==512||probe.weights.length!==512||!probe.weights.every(Number.isFinite)||!Number.isFinite(probe.bias))throw new Error('Invalid head probe');
if(probe.summary.train.missedPositivesAt080||probe.summary.test.falsePositivesAt080)throw new Error('Candidate failed training or negative regression checks');
const parameters={dimensions:512,weights:probe.weights,bias:probe.bias};
const hash=createHash('sha256').update(JSON.stringify(parameters)).digest('hex');
const output='analytics-engine/src/inference/helmet-head-probe.ts';
fs.writeFileSync(output,'// Generated by scratch/package-helmet-head-probe-20261007.mjs.\n'+
 '// Frozen CLIP features with a locally trained binary head classifier.\n'+
 'export const HELMET_HEAD_PROBE_SHA256 = '+JSON.stringify(hash)+';\n'+
 'export const HELMET_HEAD_PROBE = '+JSON.stringify(parameters)+' as const;\n');
const artifact='tmp/helmet-clip-candidate-20261007/vision_model_quantized.onnx';
const bytes=fs.readFileSync(artifact),artifactHash=createHash('sha256').update(bytes).digest('hex');
if(artifactHash!==probe.featureModelSha256)throw new Error('Feature model checksum mismatch');
const target='analytics-engine/models/safety/helmet-head-embedding.onnx';
if(fs.existsSync(target)&&createHash('sha256').update(fs.readFileSync(target)).digest('hex')!==artifactHash)throw new Error('Refusing to replace a different existing feature model');
fs.copyFileSync(artifact,target);
const manifestPath='analytics-engine/models/manifest.json';
const manifest=JSON.parse(fs.readFileSync(manifestPath,'utf8'));
const entry={id:'helmet-head-evidence',name:'Motorcycle helmet head evidence (CLIP linear probe)',
 path:'safety/helmet-head-embedding.onnx',sha256:artifactHash,
 sourceUrl:'https://huggingface.co/Xenova/clip-vit-base-patch32/resolve/d15189d7028b43f1d3e65039190477f6af591c2a/onnx/vision_model_quantized.onnx',
 sourceProject:'https://github.com/openai/CLIP',license:'MIT',type:'onnx',priority:'high',required:false,warmup:false,
 useGPU:true,task:'helmet-classification',preprocessor:'clip-center-crop',postprocessor:'clip-linear-head',
 labels:['wearing_helmet','unwearing_helmet'],inputShape:[1,3,224,224]};
const previous=manifest.models.findIndex(m=>m.id===entry.id);
if(previous<0)manifest.models.push(entry);else manifest.models[previous]=entry;
fs.writeFileSync(manifestPath,JSON.stringify(manifest,null,2)+'\n');
console.log(JSON.stringify({module:output,probeSha256:hash,artifact:target,artifactSha256:artifactHash}));
